makeMtLab(document.getElementById("lab-l17"),{id:"l17",scenarios:[{"label": "Ví dụ: 1111 1111 là 255 hay −1?", "note": "Bit cao nhất có trọng số −128 khi đọc có dấu.", "steps": [{"t": "Một byte: 1111 1111", "html": "<p class=\"mt-calc\">Cùng 8 bit, hai cách hiểu<\/p>", "say": "<p>Bit không mang ý nghĩa sẵn; chương trình quyết định đọc nó là số không dấu hay có dấu.<\/p>"}, {"t": "Không dấu: 255", "html": "<table class=\"mt-tab\"><thead><tr><th scope=\"col\">Trọng số<\/th><th scope=\"col\">128<\/th><th scope=\"col\">64<\/th><th scope=\"col\">32<\/th><th scope=\"col\">16<\/th><th scope=\"col\">8<\/th><th scope=\"col\">4<\/th><th scope=\"col\">2<\/th><th scope=\"col\">1<\/th><\/tr><\/thead><tbody><tr><td>Bit<\/td><td>1<\/td><td>1<\/td><td>1<\/td><td>1<\/td><td>1<\/td><td>1<\/td><td>1<\/td><td>1<\/td><\/tr><\/tbody><\/table><p class=\"mt-calc\">Tổng = <b>255<\/b><\/p>"}, {"t": "Có dấu (bù hai): −1", "html": "<table class=\"mt-tab\"><thead><tr><th scope=\"col\">Trọng số<\/th><th scope=\"col\">−128<\/th><th scope=\"col\">64<\/th><th scope=\"col\">32<\/th><th scope=\"col\">16<\/th><th scope=\"col\">8<\/th><th scope=\"col\">4<\/th><th scope=\"col\">2<\/th><th scope=\"col\">1<\/th><\/tr><\/thead><tbody><tr><td>Bit<\/td><td class=\"new\">1<\/td><td>1<\/td><td>1<\/td><td>1<\/td><td>1<\/td><td>1<\/td><td>1<\/td><td>1<\/td><\/tr><\/tbody><\/table><p class=\"mt-calc\">−128 + 64 + 32 + 16 + 8 + 4 + 2 + 1 = <b>−1<\/b><\/p>", "ask": {"q": "Trong bù hai 8 bit, bit cao nhất có trọng số bao nhiêu?", "o": ["+128", "−128", "0"], "a": 1}, "say": "<p>Trong bù hai, bit cao nhất có trọng số <b>âm<\/b>: −2ⁿ⁻¹. Mọi bit khác giữ trọng số dương như thường. Miền giá trị 8 bit: −128 … 127.<\/p>"}]}, {"label": "Ví dụ: Tìm −5 bằng đảo bit cộng 1", "note": "Kiểm tra lại bằng tổng trọng số.", "steps": [{"t": "Muốn biểu diễn −5 trong 8 bit", "html": "<p class=\"mt-calc\">5 = 0000 0101<\/p>", "say": "<p>Quy tắc: đảo mọi bit rồi cộng 1.<\/p>"}, {"t": "Đảo mọi bit: 1111 1010", "html": "<p class=\"mt-calc\">~0000 0101 = 1111 1010<\/p>"}, {"t": "Cộng 1: 1111 1011 = −5", "html": "<p class=\"mt-calc\">1111 1010 + 1 = <b>1111 1011<\/b><\/p><table class=\"mt-tab\"><thead><tr><th scope=\"col\">Trọng số<\/th><th scope=\"col\">−128<\/th><th scope=\"col\">64<\/th><th scope=\"col\">32<\/th><th scope=\"col\">16<\/th><th scope=\"col\">8<\/th><th scope=\"col\">4<\/th><th scope=\"col\">2<\/th><th scope=\"col\">1<\/th><\/tr><\/thead><tbody><tr><td>Bit<\/td><td>1<\/td><td>1<\/td><td>1<\/td><td>1<\/td><td>1<\/td><td>0<\/td><td>1<\/td><td>1<\/td><\/tr><\/tbody><\/table><p class=\"mt-calc\">−128 + 64 + 32 + 16 + 8 + 2 + 1 = −5 ✓<\/p>", "ask": {"q": "Đảo bit của 0000 0101 được 1111 1010. Bước tiếp theo để được −5?", "o": ["Cộng 1", "Trừ 1", "Đảo lại"], "a": 0}, "say": "<p>Kiểm tra nhanh: −5 + 5 phải bằng 0: 1111 1011 + 0000 0101 = 1 0000 0000, bỏ bit thứ 9 còn 0 ✓.<\/p>"}]}, {"label": "Ví dụ: 5 + (−3) bằng bộ cộng không dấu", "note": "Bỏ bit nhớ ra ngoài; cờ C = 1 không có nghĩa là sai.", "steps": [{"t": "5 + (−3) với cùng một bộ cộng", "html": "<table class=\"mt-tab\"><thead><tr><th scope=\"col\"><\/th><th scope=\"col\">Bit<\/th><\/tr><\/thead><tbody><tr><td>5<\/td><td>0000 0101<\/td><\/tr><tr><td>−3<\/td><td>1111 1101<\/td><\/tr><\/tbody><\/table>", "say": "<p>Điểm hay nhất của bù hai: phép cộng số có dấu dùng đúng bộ cộng của số không dấu (Bài 5).<\/p>"}, {"t": "Cộng: 1 0000 0010, bỏ bit thứ 9", "html": "<p class=\"mt-calc\">0000 0101 + 1111 1101 = 1 <b>0000 0010<\/b> · cờ nhớ C = 1 · kết quả 8 bit = 2 ✓<\/p>", "ask": {"q": "Cờ nhớ C = 1 khi cộng 5 + (−3). Kết quả có dấu có sai không?", "o": ["Sai, vì có nhớ", "Đúng, bằng 2; cờ nhớ chỉ báo tràn cho số không dấu"], "a": 1}, "say": "<p>Với số có dấu, tràn được báo bằng cờ khác: cờ tràn V. Ở đây V = 0, kết quả đúng.<\/p>"}]}, {"label": "Bẫy: 100 + 50 tràn có dấu", "note": "Hai số dương cộng ra bit dấu bằng 1: V = 1.", "steps": [{"t": "100 + 50 trong 8 bit có dấu", "html": "<table class=\"mt-tab\"><thead><tr><th scope=\"col\"><\/th><th scope=\"col\">Bit<\/th><th scope=\"col\">Có dấu<\/th><\/tr><\/thead><tbody><tr><td>100<\/td><td>0110 0100<\/td><td>100<\/td><\/tr><tr><td>50<\/td><td>0011 0010<\/td><td>50<\/td><\/tr><\/tbody><\/table>", "say": "<p>Miền có dấu 8 bit chỉ tới 127, mà 150 > 127.<\/p>"}, {"t": "Kết quả 1001 0110: đọc có dấu là −106", "html": "<p class=\"mt-calc\">0110 0100 + 0011 0010 = <b>1001 0110<\/b> · không dấu = 150 · có dấu = −106 · C = 0, V = 1<\/p>", "ask": {"q": "Cộng hai số dương mà kết quả có bit dấu bằng 1. Điều đó báo hiệu gì?", "o": ["Kết quả âm thật", "Tràn số có dấu (V = 1)", "Cờ nhớ C = 1"], "a": 1}}, {"t": "Quy tắc nhận biết tràn có dấu", "html": "<table class=\"mt-tab\"><thead><tr><th scope=\"col\">Hai số hạng<\/th><th scope=\"col\">Kết quả<\/th><th scope=\"col\">Tràn có dấu?<\/th><\/tr><\/thead><tbody><tr><td>Cùng dương<\/td><td>âm<\/td><td class=\"bad\">có<\/td><\/tr><tr><td>Cùng âm<\/td><td>dương<\/td><td class=\"bad\">có<\/td><\/tr><tr><td>Khác dấu<\/td><td>bất kỳ<\/td><td class=\"ok\">không bao giờ<\/td><\/tr><\/tbody><\/table>", "say": "<p>Phần cứng tính cả hai cờ trong một lần cộng; chương trình dùng C nếu coi số là không dấu, dùng V nếu coi là có dấu. Ngôn ngữ C/C++ coi tràn số có dấu là hành vi không xác định, nên không được dựa vào “quay vòng” của số có dấu.<\/p>"}]}, {"label": "Bẫy: Số đối của −128", "note": "Miền bù hai không đối xứng.", "steps": [{"t": "−128 = 1000 0000", "html": "<table class=\"mt-tab\"><thead><tr><th scope=\"col\">Trọng số<\/th><th scope=\"col\">−128<\/th><th scope=\"col\">64<\/th><th scope=\"col\">32<\/th><th scope=\"col\">16<\/th><th scope=\"col\">8<\/th><th scope=\"col\">4<\/th><th scope=\"col\">2<\/th><th scope=\"col\">1<\/th><\/tr><\/thead><tbody><tr><td>Bit<\/td><td>1<\/td><td>0<\/td><td>0<\/td><td>0<\/td><td>0<\/td><td>0<\/td><td>0<\/td><td>0<\/td><\/tr><\/tbody><\/table>"}, {"t": "Đảo bit: 0111 1111; cộng 1: 1000 0000", "html": "<p class=\"mt-calc\">Kết quả lại là 1000 0000 = −128<\/p>", "ask": {"q": "Lấy đối của −128 trong 8 bit bù hai được gì?", "o": ["128", "−128 (tràn)", "0"], "a": 1}}, {"t": "Miền không đối xứng: −128 … 127", "html": "<p class=\"mt-calc\">Có 128 số âm nhưng chỉ 127 số dương (cộng thêm số 0)<\/p>", "say": "<p>Giá trị âm nhỏ nhất không có số đối trong cùng độ rộng. Hàm “trị tuyệt đối” trên số 8 bit vì vậy có một trường hợp tràn.<\/p>"}]}, {"label": "Lỗi: Mở rộng −5 bằng số 0", "note": "Số có dấu phải mở rộng bằng bit dấu.", "steps": [{"t": "Đổi −5 từ 8 bit sang 16 bit", "html": "<p class=\"mt-calc\">−5 (8 bit) = 1111 1011<\/p>", "say": "<p>Biến 8 bit được gán vào biến 16 bit: các bit cao mới điền gì?<\/p>"}, {"t": "Sai: điền 0 → 0000 0000 1111 1011 = 251", "html": "<p class=\"mt-calc\">0000 0000 1111 1011 = <b>251<\/b> ✗<\/p>", "ask": {"q": "Mở rộng số có dấu âm sang nhiều bit hơn, bit cao mới phải là gì?", "o": ["Toàn 0", "Chép bit dấu (toàn 1)", "Tùy ý"], "a": 1}}, {"t": "Đúng: chép bit dấu → 1111 1111 1111 1011 = −5", "html": "<p class=\"mt-calc\">1111 1111 1111 1011 = <b>-5<\/b> ✓<\/p>", "say": "<p>Mở rộng dấu giữ nguyên giá trị có dấu. Điền 0 (mở rộng bằng 0) chỉ đúng cho số không dấu. Lỗi này hay gặp khi đọc dữ liệu cảm biến 8 bit hoặc 16 bit có dấu vào biến rộng hơn.<\/p>"}]}, {"label": "Lỗi: Trộn có dấu và không dấu khi so sánh", "note": "Cùng bit 1100 1000: 200 hay −56.", "steps": [{"t": "Hai biến cùng chứa 1100 1000", "html": "<p class=\"mt-calc\">Không dấu: 200 · có dấu: -56<\/p>", "say": "<p>Một chương trình so sánh hai giá trị đọc từ thiết bị, một biến khai báo có dấu, biến kia không dấu.<\/p>"}, {"t": "So sánh “200 > 100”: đúng hay sai tùy kiểu", "html": "<table class=\"mt-tab\"><thead><tr><th scope=\"col\">Coi là<\/th><th scope=\"col\">Giá trị<\/th><th scope=\"col\">> 100 ?<\/th><\/tr><\/thead><tbody><tr><td>không dấu<\/td><td>200<\/td><td>đúng<\/td><\/tr><tr><td>có dấu<\/td><td>−56<\/td><td class=\"bad\">sai<\/td><\/tr><\/tbody><\/table>", "ask": {"q": "Byte 1100 1000 được đọc như số có dấu 8 bit. Nó có lớn hơn 100 không?", "o": ["Có, vì bằng 200", "Không, vì bằng −56"], "a": 1}}, {"t": "Sửa: thống nhất kiểu trước khi so sánh", "html": "<p class=\"mt-calc\">Ghi rõ trong đặc tả dữ liệu: độ rộng, có dấu hay không; đổi kiểu tường minh trước khi tính<\/p>", "say": "<p>Khi đọc tài liệu thiết bị, luôn tìm dòng “signed/unsigned”, “INT16/UINT16”. Bài 20 nói thêm về thứ tự byte.<\/p>"}]}]});
makeMtEx(document.getElementById("ex-l17"),"l17",[{"kind": "num", "t": "Đọc số 8 bit", "d": "<p>Ghi giá trị ở hệ 10 (số âm có dấu trừ).<\/p>", "items": [{"q": "1111 1011 đọc có dấu", "a": -5}, {"q": "1111 1011 đọc không dấu", "a": 251}, {"q": "1000 0000 đọc có dấu", "a": -128}, {"q": "0111 1111 đọc có dấu", "a": 127}, {"q": "1110 1100 đọc có dấu", "a": -20}], "hints": ["Có dấu: bit cao nhất có trọng số −128.", "Hoặc: lấy giá trị không dấu trừ 256 nếu bit cao nhất bằng 1.", "1110 1100 không dấu = 236; 236 − 256."], "why": "251 − 256 = −5; không dấu 251; 1000 0000 = −128; 0111 1111 = 127; 236 − 256 = −20."}, {"kind": "num", "t": "Bù hai và tràn", "d": "<p>Số 8 bit có dấu. Câu hỏi về bit thì ghi dãy bit (chỉ chữ số 0, 1); câu hỏi về cờ thì ghi 0 hoặc 1.<\/p>", "items": [{"q": "Dãy bit của −20 (8 bit)?", "a": 11101100}, {"q": "100 + 50: giá trị có dấu thu được?", "a": -106}, {"q": "100 + 50: cờ V?", "a": 1}, {"q": "(−100) + 50: cờ V?", "a": 0}, {"q": "(−100) + (−50): giá trị có dấu thu được?", "a": 106}], "hints": ["−20: 20 = 0001 0100 → đảo → cộng 1.", "Kết quả 8 bit = tổng mod 256, rồi đọc có dấu.", "Hai số khác dấu không bao giờ tràn có dấu."], "why": "−20 = 1110 1100; 150 − 256 = −106 với V = 1; khác dấu nên V = 0; −150 + 256 = 106 (tràn: hai số âm ra số dương)."}, {"kind": "num", "t": "Miền giá trị và mở rộng", "d": "<p>Ghi số ở hệ 10.<\/p>", "items": [{"q": "Số nhỏ nhất của số có dấu 16 bit?", "a": -32768}, {"q": "Số lớn nhất của số có dấu 32 bit?", "a": 2147483647}, {"q": "−5 (8 bit) mở rộng bằng 0 lên 16 bit, đọc có dấu, ra bao nhiêu?", "a": 251}, {"q": "0xFFFB đọc như số có dấu 16 bit?", "a": -5}], "hints": ["Có dấu n bit: −2ⁿ⁻¹ … 2ⁿ⁻¹ − 1.", "Mở rộng bằng 0: bit dấu mới bằng 0 nên kết quả dương.", "0xFFFB = 65 531; 65 531 − 65 536."], "why": "−2¹⁵ = −32 768; 2³¹ − 1 = 2 147 483 647; 0000 0000 1111 1011 = 251; 65 531 − 65 536 = −5."}]);

